  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Admin {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  name      String\n  role      String? // was AdminRole\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"admins\")\n}\n\nmodel Alumni {\n  id             String    @id @default(cuid())\n  email          String    @unique\n  password       String?\n  name           String\n  profilePicture String?\n  phone          String?\n  graduationYear Int\n  // department removed\n  degree         String\n  currentJob     String?\n  currentCompany String?\n  location       String?\n  bio            String?\n  skills         String? // was String[]\n  interests      String? // was String[]\n  linkedinUrl    String?\n  githubUrl      String?\n  websiteUrl     String?\n  isVerified     Boolean   @default(false)\n  isPublic       Boolean   @default(true)\n  emailVerified  Boolean   @default(false)\n  lastLogin      DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  // Relations\n  donations          Donation[]\n  jobApplications    JobApplication[]\n  postedJobs         Job[]\n  eventRegistrations EventRegistration[]\n  successStories     SuccessStory[]\n  feedbacks          Feedback[]\n  sentMessages       Message[]           @relation(\"SentMessages\")\n  receivedMessages   Message[]           @relation(\"ReceivedMessages\")\n  followers          Follow[]            @relation(\"Followers\")\n  following          Follow[]            @relation(\"Following\")\n  mentorships        Mentorship[]        @relation(\"Mentor\")\n  mentees            Mentorship[]        @relation(\"Mentee\")\n\n  @@map(\"alumni\")\n}\n\nmodel Job {\n  id              String   @id @default(cuid())\n  title           String\n  description     String\n  company         String\n  location        String\n  jobType         String? // was JobType\n  experienceLevel String? // was ExperienceLevel\n  skills          String? // was String[]\n  salary          String?\n  applicationUrl  String?\n  isActive        Boolean  @default(true)\n  postedById      String\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  // Relations\n  postedBy     Alumni           @relation(fields: [postedById], references: [id], onDelete: Cascade)\n  applications JobApplication[]\n\n  @@map(\"jobs\")\n}\n\nmodel JobApplication {\n  id          String   @id @default(cuid())\n  jobId       String\n  alumniId    String\n  resume      String?\n  coverLetter String?\n  status      String?  @default(\"PENDING\") // was ApplicationStatus\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  job    Job    @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  alumni Alumni @relation(fields: [alumniId], references: [id], onDelete: Cascade)\n\n  @@unique([jobId, alumniId])\n  @@map(\"job_applications\")\n}\n\nmodel Event {\n  id           String    @id @default(cuid())\n  title        String\n  description  String\n  location     String\n  eventDate    DateTime\n  endDate      DateTime?\n  image        String?\n  ticketPrice  Float?    @default(0)\n  maxAttendees Int?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  // Relations\n  registrations EventRegistration[]\n\n  @@map(\"events\")\n}\n\nmodel EventRegistration {\n  id        String   @id @default(cuid())\n  eventId   String\n  alumniId  String\n  status    String?  @default(\"REGISTERED\") // was RegistrationStatus\n  checkedIn Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  event  Event  @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  alumni Alumni @relation(fields: [alumniId], references: [id], onDelete: Cascade)\n\n  @@unique([eventId, alumniId])\n  @@map(\"event_registrations\")\n}\n\nmodel Donation {\n  id            String   @id @default(cuid())\n  alumniId      String\n  amount        Float\n  currency      String   @default(\"USD\")\n  purpose       String?\n  paymentMethod String? // was PaymentMethod\n  transactionId String?\n  status        String?  @default(\"PENDING\") // was DonationStatus\n  receipt       String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Relations\n  alumni Alumni @relation(fields: [alumniId], references: [id], onDelete: Cascade)\n\n  @@map(\"donations\")\n}\n\nmodel SuccessStory {\n  id         String   @id @default(cuid())\n  alumniId   String\n  title      String\n  content    String\n  image      String?\n  proofLink  String?\n  isApproved Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  // Relations\n  alumni Alumni @relation(fields: [alumniId], references: [id], onDelete: Cascade)\n\n  @@map(\"success_stories\")\n}\n\nmodel Feedback {\n  id        String   @id @default(cuid())\n  alumniId  String\n  category  String? // was FeedbackCategory\n  subject   String\n  message   String\n  rating    Int?\n  status    String?  @default(\"OPEN\") // was FeedbackStatus\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  alumni Alumni @relation(fields: [alumniId], references: [id], onDelete: Cascade)\n\n  @@map(\"feedbacks\")\n}\n\nmodel Message {\n  id         String   @id @default(cuid())\n  senderId   String\n  receiverId String\n  content    String\n  isRead     Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  // Relations\n  sender   Alumni @relation(\"SentMessages\", fields: [senderId], references: [id], onDelete: Cascade)\n  receiver Alumni @relation(\"ReceivedMessages\", fields: [receiverId], references: [id], onDelete: Cascade)\n\n  @@map(\"messages\")\n}\n\nmodel Follow {\n  id          String   @id @default(cuid())\n  followerId  String\n  followingId String\n  createdAt   DateTime @default(now())\n\n  // Relations\n  follower  Alumni @relation(\"Followers\", fields: [followerId], references: [id], onDelete: Cascade)\n  following Alumni @relation(\"Following\", fields: [followingId], references: [id], onDelete: Cascade)\n\n  @@unique([followerId, followingId])\n  @@map(\"follows\")\n}\n\nmodel Mentorship {\n  id        String   @id @default(cuid())\n  mentorId  String\n  menteeId  String\n  status    String?  @default(\"PENDING\") // was MentorshipStatus\n  message   String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  mentor Alumni @relation(\"Mentor\", fields: [mentorId], references: [id], onDelete: Cascade)\n  mentee Alumni @relation(\"Mentee\", fields: [menteeId], references: [id], onDelete: Cascade)\n\n  @@unique([mentorId, menteeId])\n  @@map(\"mentorships\")\n}\n",
